//! The trained one-layer, four-head transformer on addition mod 113, as a fixed-width integer
//! program in safe Rust (gate 5).
//!
//! The weights in [`weights`] are generated by `scripts/gen_transformer_weights.py` from
//! lean-checked-network's `transformer/runs/best.npz`, quantised at `S = 256`. The nine matrices
//! are the integers of the model behind `TransformerBridge.FinalRaw.raw_model_adds_mod_113`.
//!
//! The input is the token sequence `[a, b, =]`. Only the last position is evaluated: token and
//! position embedding, four attention heads, residual, MLP with ReLU, residual, unembedding,
//! argmax with the first index on a tie.
//!
//! Every number is an `i64`. There is no floating point. Each stage has one fixed scale:
//!
//! | Stage | Value | Scale |
//! | --- | --- | --- |
//! | [`embed`] | `x = TOK[tok] + POS[pos]` | 2^8 |
//! | [`project`] | query, key and value vectors | 2^16 |
//! | [`head_scores`] | `s = q . k` | 2^32 |
//! | [`exp_fix`] | `e = 2^30 * exp(-d / 2^32)`, from tables | 2^30 |
//! | [`softmax_weights`] | `alpha = e * 2^24 / (e0 + e1 + e2)` | 2^24 |
//! | [`head_output`] | `z = (alpha0 * v0 + alpha1 * v1 + alpha2 * v2) >> 16`, then `z` times `WO` | 2^24, then 2^32 |
//! | [`residual`] | `r = x2 * 2^24 + att` | 2^32 |
//! | [`mlp_hidden`] | `m = relu(r * WIN + BIN * 2^8) >> 8` | 2^32 |
//! | [`mlp_output`] | `o = m * WOUT + BOUT` | 2^40 |
//! | [`final_stream`] | `fin = (r * 2^8 + o) >> 16` | 2^24 |
//! | [`unembed`] | `logits = fin * U` | 2^32 |
//!
//! Rounding. `>>` on an `i64` is the arithmetic shift, which rounds toward minus infinity. The
//! one division, in [`softmax_weights`], has a numerator that is not negative and a positive
//! denominator, so it rounds down too.
//!
//! The code is written for a verifier that reads MIR: `while` loops with explicit indices over
//! fixed-size arrays, no iterators, no closures, no generics, no allocation.
#![no_std]
#![forbid(unsafe_code)]

#[rustfmt::skip]
pub mod weights;

use weights::{
    BIN, BOUT, EXP_0, EXP_1, EXP_2, EXP_FRAC_BITS, EXP_N, EXP_ONE, POS, TOK, U, WIN, WK, WO, WOUT,
    WQ, WV,
};

/// The modulus. Inputs and answers are `0..113`.
pub const P: usize = 113;
/// Number of tokens: `0..113` and `=`.
pub const VOCAB: usize = 114;
/// The token `=`.
pub const EQ: usize = 113;
/// Number of positions: `a`, `b`, `=`.
pub const N_POS: usize = 3;
/// Width of the residual stream.
pub const D_MODEL: usize = 128;
/// Number of attention heads.
pub const N_HEADS: usize = 4;
/// Width of one head.
pub const D_HEAD: usize = 32;
/// Width of the MLP hidden layer.
pub const D_MLP: usize = 512;

/// A softmax weight of 1, scale 2^24.
pub const ALPHA_ONE: i64 = 1 << 24;
/// Number of entries of `EXP_N`. `exp_fix` returns 0 from this many whole units on.
pub const EXP_N_LEN: i64 = 32;

/// Token plus position embedding, scale 2^8. Needs `tok < 114` and `pos < 3`.
pub fn embed(tok: usize, pos: usize) -> [i64; D_MODEL] {
    let mut x = [0i64; D_MODEL];
    let mut k = 0;
    while k < D_MODEL {
        x[k] = TOK[tok][k] as i64 + POS[pos][k] as i64;
        k += 1;
    }
    x
}

/// A stream vector times a 128 by 32 matrix: `out[i] = sum over k of x[k] * w[k][i]`.
/// Used for the query, key and value vectors, scale 2^16.
pub fn project(x: &[i64; D_MODEL], w: &[[i8; D_HEAD]; D_MODEL]) -> [i64; D_HEAD] {
    let mut out = [0i64; D_HEAD];
    let mut i = 0;
    while i < D_HEAD {
        let mut acc = 0i64;
        let mut k = 0;
        while k < D_MODEL {
            acc += x[k] * (w[k][i] as i64);
            k += 1;
        }
        out[i] = acc;
        i += 1;
    }
    out
}

/// The three attention scores of head `h`, read at the last position, scale 2^32:
/// `s[j] = (x[2] * WQ[h]) . (x[j] * WK[h])`. Needs `h < 4`.
pub fn head_scores(h: usize, x: &[[i64; D_MODEL]; N_POS]) -> [i64; N_POS] {
    let q = project(&x[2], &WQ[h]);
    let mut s = [0i64; N_POS];
    let mut j = 0;
    while j < N_POS {
        let key = project(&x[j], &WK[h]);
        let mut acc = 0i64;
        let mut i = 0;
        while i < D_HEAD {
            acc += q[i] * key[i];
            i += 1;
        }
        s[j] = acc;
        j += 1;
    }
    s
}

/// Integer stand-in for `2^30 * exp(-d / 2^32)`, for `d >= 0`.
///
/// `d` is cut to 24 fractional bits, `u = d >> 8`, and split as
/// `u = n * 2^24 + b2 * 2^16 + b1 * 2^8 + b0`. The result is the product of the four table
/// entries `EXP_N[n]`, `EXP_2[b2]`, `EXP_1[b1]`, `EXP_0[b0]`, with a shift by 30 after each
/// multiplication. It is `2^30` at `d = 0` and `0` when `n >= 32`. A negative `d` does not occur
/// in this program and gives `2^30`.
pub fn exp_fix(d: i64) -> i64 {
    if d <= 0 {
        return EXP_ONE;
    }
    let u = d >> 8;
    let n = u >> 24;
    if n >= EXP_N_LEN {
        return 0;
    }
    let b2 = (u >> 16) & 255;
    let b1 = (u >> 8) & 255;
    let b0 = u & 255;
    let mut e = EXP_N[n as usize];
    e = (e * EXP_2[b2 as usize]) >> EXP_FRAC_BITS;
    e = (e * EXP_1[b1 as usize]) >> EXP_FRAC_BITS;
    e = (e * EXP_0[b0 as usize]) >> EXP_FRAC_BITS;
    e
}

/// The softmax of three scores, scale 2^24:
/// `alpha[j] = e[j] * 2^24 / (e[0] + e[1] + e[2])` with `e[j] = exp_fix(max(s) - s[j])`.
/// The largest score has `e = 2^30`, so the denominator is at least `2^30`.
pub fn softmax_weights(s: &[i64; N_POS]) -> [i64; N_POS] {
    let mut smax = s[0];
    let mut j = 1;
    while j < N_POS {
        if s[j] > smax {
            smax = s[j];
        }
        j += 1;
    }
    let mut e = [0i64; N_POS];
    let mut den = 0i64;
    j = 0;
    while j < N_POS {
        e[j] = exp_fix(smax - s[j]);
        den += e[j];
        j += 1;
    }
    let mut alpha = [0i64; N_POS];
    j = 0;
    while j < N_POS {
        alpha[j] = (e[j] * ALPHA_ONE) / den;
        j += 1;
    }
    alpha
}

/// What head `h` adds to the residual stream, scale 2^32. The value vectors `x[j] * WV[h]`
/// (scale 2^16) are mixed with the softmax weights (scale 2^24), shifted down to scale 2^24,
/// and multiplied by `WO[h]`. Needs `h < 4`.
pub fn head_output(
    h: usize,
    x: &[[i64; D_MODEL]; N_POS],
    alpha: &[i64; N_POS],
) -> [i64; D_MODEL] {
    let v0 = project(&x[0], &WV[h]);
    let v1 = project(&x[1], &WV[h]);
    let v2 = project(&x[2], &WV[h]);
    let mut z = [0i64; D_HEAD];
    let mut i = 0;
    while i < D_HEAD {
        z[i] = (alpha[0] * v0[i] + alpha[1] * v1[i] + alpha[2] * v2[i]) >> 16;
        i += 1;
    }
    let mut out = [0i64; D_MODEL];
    let mut k = 0;
    while k < D_MODEL {
        let mut acc = 0i64;
        let mut t = 0;
        while t < D_HEAD {
            acc += z[t] * (WO[h][t][k] as i64);
            t += 1;
        }
        out[k] = acc;
        k += 1;
    }
    out
}

/// The sum of the four heads' outputs, scale 2^32.
pub fn attention(x: &[[i64; D_MODEL]; N_POS]) -> [i64; D_MODEL] {
    let mut att = [0i64; D_MODEL];
    let mut h = 0;
    while h < N_HEADS {
        let s = head_scores(h, x);
        let alpha = softmax_weights(&s);
        let w = head_output(h, x, &alpha);
        let mut k = 0;
        while k < D_MODEL {
            att[k] += w[k];
            k += 1;
        }
        h += 1;
    }
    att
}

/// The residual stream after attention, scale 2^32: `x2 * 2^24 + att`.
pub fn residual(x2: &[i64; D_MODEL], att: &[i64; D_MODEL]) -> [i64; D_MODEL] {
    let mut r = [0i64; D_MODEL];
    let mut k = 0;
    while k < D_MODEL {
        r[k] = x2[k] * ALPHA_ONE + att[k];
        k += 1;
    }
    r
}

/// The MLP hidden layer after ReLU, scale 2^32:
/// `m[i] = relu(sum over k of r[k] * WIN[k][i] + BIN[i] * 2^8) >> 8`.
pub fn mlp_hidden(r: &[i64; D_MODEL]) -> [i64; D_MLP] {
    let mut m = [0i64; D_MLP];
    let mut i = 0;
    while i < D_MLP {
        let mut acc = 0i64;
        let mut k = 0;
        while k < D_MODEL {
            acc += r[k] * (WIN[k][i] as i64);
            k += 1;
        }
        let pre = acc + BIN[i] * 256;
        if pre > 0 {
            m[i] = pre >> 8;
        }
        i += 1;
    }
    m
}

/// The MLP output, scale 2^40: `o[k] = sum over i of m[i] * WOUT[i][k] + BOUT[k]`.
pub fn mlp_output(m: &[i64; D_MLP]) -> [i64; D_MODEL] {
    let mut o = [0i64; D_MODEL];
    let mut k = 0;
    while k < D_MODEL {
        let mut acc = 0i64;
        let mut i = 0;
        while i < D_MLP {
            acc += m[i] * (WOUT[i][k] as i64);
            i += 1;
        }
        o[k] = acc + BOUT[k];
        k += 1;
    }
    o
}

/// The final residual stream, scale 2^24: `(r * 2^8 + o) >> 16`.
pub fn final_stream(r: &[i64; D_MODEL], o: &[i64; D_MODEL]) -> [i64; D_MODEL] {
    let mut fin = [0i64; D_MODEL];
    let mut k = 0;
    while k < D_MODEL {
        fin[k] = (r[k] * 256 + o[k]) >> 16;
        k += 1;
    }
    fin
}

/// The 113 logits, scale 2^32: `out[c] = sum over k of fin[k] * U[k][c]`.
pub fn unembed(fin: &[i64; D_MODEL]) -> [i64; P] {
    let mut out = [0i64; P];
    let mut c = 0;
    while c < P {
        let mut acc = 0i64;
        let mut k = 0;
        while k < D_MODEL {
            acc += fin[k] * (U[k][c] as i64);
            k += 1;
        }
        out[c] = acc;
        c += 1;
    }
    out
}

/// Index of the largest entry, the first one on a tie.
pub fn argmax(l: &[i64; P]) -> usize {
    let mut best = 0;
    let mut best_value = l[0];
    let mut c = 1;
    while c < P {
        if l[c] > best_value {
            best_value = l[c];
            best = c;
        }
        c += 1;
    }
    best
}

/// The logits for the tokens `[a, b, =]`, scale 2^32. Needs `a < 113` and `b < 113`.
pub fn forward(a: usize, b: usize) -> [i64; P] {
    let x = [embed(a, 0), embed(b, 1), embed(EQ, 2)];
    let att = attention(&x);
    let r = residual(&x[2], &att);
    let m = mlp_hidden(&r);
    let o = mlp_output(&m);
    let fin = final_stream(&r, &o);
    unembed(&fin)
}

/// `Some(logits)` for `a, b < 113`; `None` otherwise. Never panics.
pub fn logits(a: usize, b: usize) -> Option<[i64; P]> {
    if a >= P || b >= P {
        return None;
    }
    Some(forward(a, b))
}

/// `Some(answer)` for `a, b < 113`; `None` otherwise. Never panics.
pub fn predict(a: usize, b: usize) -> Option<usize> {
    if a >= P || b >= P {
        return None;
    }
    let l = forward(a, b);
    Some(argmax(&l))
}
